package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;
public class AuditLogActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Audit Log","Traceable actions recorded by the prototype workspace.");DatabaseManager m=new DatabaseManager(this);String uid=new AuthManager(this).getUserId();Cursor c=m.getDatabase().rawQuery("SELECT action,resource_type,resource_id,timestamp,result FROM audit_logs WHERE user_id=? ORDER BY timestamp DESC",new String[]{uid});try{if(!c.moveToFirst())root.addView(utils.text(this,"No audit entries yet.",15,0xff71808f,false));else do{LinearLayout box=utils.column(this);utils.row(box,this,"Action",c.getString(0));utils.row(box,this,"Resource",c.getString(1)+" / "+c.getString(2));utils.row(box,this,"Result",c.getString(4));utils.row(box,this,"Time",c.getString(3));utils.addCard(root,box,this);}while(c.moveToNext());}finally{c.close();}utils.setScreenContentView(this, root);}}
